insert into public.spots (id, city, name, cat, price, hood, address, "desc", tip, pick, photo, credit, source) values
  ('s01', 'paris', 'Bouillon Chartier', 'Restaurant', 'p1', 'Grands Boulevards', '7 Rue du Faubourg Montmartre, 75009 Paris', 'Brasserie historique de 1896, plats français classiques à petits prix. Pas de réservation : on fait la queue.', 'Venez avant 12h ou après 14h pour éviter l''attente.', true, 'img/s01.jpg', 'Michel wal · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Paris_Chartier_1304.jpg'),
  ('s02', 'paris', 'Musée d''Orsay', 'Culture', 'p2', '7e arrondissement', 'Esplanade Valéry Giscard d''Estaing, 75007 Paris', 'Impressionnistes et art du XIXe siècle dans une ancienne gare.', 'Gratuit le premier dimanche du mois, réservez quand même un créneau.', false, 'img/s02.jpg', 'Daniel Lu (User:dllu) · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Musee_d_Orsay_main_hall_Paris_2023_dllu.jpg'),
  ('s03', 'paris', 'Canal Saint-Martin', 'Activité', 'free', '10e arrondissement', 'Quai de Valmy, 75010 Paris', 'Balade le long des écluses et des passerelles, pique-nique au bord de l''eau.', 'Le dimanche, les quais sont piétons.', false, 'img/s03.jpg', 'Superbass · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:2022-04-14-Passerelle_de_la_Grange-aux-Belles-8583.jpg'),
  ('s04', 'paris', 'Septime', 'Restaurant', 'p3', '11e arrondissement', '80 Rue de Charonne, 75011 Paris', 'Cuisine de saison en menu dégustation, l''une des tables les plus demandées de Paris.', 'Les réservations ouvrent trois semaines à l''avance.', false, '', '', ''),
  ('s05', 'lisbonne', 'Pastéis de Belém', 'Restaurant', 'p1', 'Belém', 'Rua de Belém 84-92, 1300-085 Lisboa', 'La pâtisserie qui fabrique ses pastéis de nata depuis 1837.', 'Prenez place à l''intérieur : la queue à emporter est plus longue.', true, 'img/s05.jpg', 'fw42 from Germany · CC BY 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Pastel_de_nata_(18616473070).jpg'),
  ('s06', 'lisbonne', 'Miradouro da Senhora do Monte', 'Activité', 'free', 'Graça', 'Largo Monte, 1170-253 Lisboa', 'Le point de vue le plus haut de la ville, idéal au coucher du soleil.', 'Montez avec le tram 28 puis finissez à pied.', false, 'img/s06.jpg', 'Filipe Rocha,user:sacavem (pt) http://pt.wikipedia.org/wi... · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Miradouro_Nossa_Senhora_do_Monte_II.jpg'),
  ('s07', 'lisbonne', 'Time Out Market', 'Restaurant', 'p2', 'Cais do Sodré', 'Av. 24 de Julho 49, 1200-479 Lisboa', 'Halle gourmande qui réunit des stands de chefs lisboètes.', 'En semaine à midi, on trouve facilement une place.', false, 'img/s07.jpg', 'Osvaldo Gago / Osvaldo Gago · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Mercado_Ribeira_Lisbon.JPG'),
  ('s08', 'lisbonne', 'LX Factory', 'Culture', 'free', 'Alcântara', 'Rua Rodrigues de Faria 103, 1300-501 Lisboa', 'Ancienne usine devenue quartier créatif : librairies, ateliers, street art.', 'Le marché du dimanche réunit créateurs et brocanteurs.', false, 'img/s08.jpg', 'Andrzej Otrębski · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Lisboa_LX_Factory_1.jpg'),
  ('s09', 'barcelone', 'Bunkers del Carmel', 'Activité', 'free', 'El Carmel', 'Carrer de Marià Labèrnia, 08032 Barcelona', 'Anciennes batteries antiaériennes avec une vue à 360° sur la ville.', 'Prévoyez une lampe pour la descente après le coucher du soleil.', false, 'img/s09.jpg', 'Barcelonatips · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Bunkers_del_Carmel_Barcelona.jpg'),
  ('s10', 'barcelone', 'Sagrada Família', 'Culture', 'p2', 'Eixample', 'Carrer de Mallorca 401, 08013 Barcelona', 'La basilique de Gaudí, toujours en construction.', 'Billets en ligne uniquement en haute saison.', true, 'img/s10.jpg', 'Matti Blume · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Sagrada_Familia,_Barcelona_(P1170693).jpg'),
  ('s11', 'barcelone', 'El Xampanyet', 'Bar & nuit', 'p2', 'El Born', 'Carrer de Montcada 22, 08003 Barcelona', 'Bar à tapas carrelé de bleu, réputé pour son cava maison.', 'Commandez au comptoir, les tables partent vite.', false, '', '', ''),
  ('s12', 'barcelone', 'Mercat de la Boqueria', 'Restaurant', 'p1', 'La Rambla', 'La Rambla 91, 08001 Barcelona', 'Le grand marché couvert, ses jus de fruits et ses comptoirs à tapas.', 'Les stands du fond sont moins chers que ceux de l''entrée.', false, 'img/s12.jpg', 'Moheen Reeyad · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Entrance_to_Mercat_de_la_Boqueria_(01).jpg'),
  ('s13', 'rome', 'Antico Forno Roscioli', 'Restaurant', 'p1', 'Campo de'' Fiori', 'Via dei Chiavari 34, 00186 Roma', 'Boulangerie historique : pizza bianca et pizza rossa à la coupe.', 'On paie au poids, demandez un morceau de chaque.', true, '', '', ''),
  ('s14', 'rome', 'Panthéon', 'Culture', 'p1', 'Centro Storico', 'Piazza della Rotonda, 00186 Roma', 'Temple antique au dôme percé d''un oculus, parfaitement conservé.', 'Entrée payante depuis 2023, billet à petit prix.', false, 'img/s14.jpg', 'NikonZ7II · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Pantheon_(Rome)_-_Right_side_and_front.jpg'),
  ('s15', 'rome', 'Balade dans Trastevere', 'Activité', 'free', 'Trastevere', 'Piazza di Santa Maria in Trastevere, 00153 Roma', 'Ruelles pavées, lierre sur les façades et places animées le soir.', 'Montez ensuite au Gianicolo pour la vue.', false, 'img/s15.jpg', 'Krzysztof Golik · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Santa_Maria_in_Trastevere_church_in_Rome_(12).jpg'),
  ('s16', 'rome', 'Salumeria Roscioli', 'Restaurant', 'p3', 'Centro Storico', 'Via dei Giubbonari 21, 00186 Roma', 'Épicerie fine et restaurant, célèbre pour sa carbonara.', 'Réservation indispensable le soir.', false, '', '', ''),
  ('s17', 'berlin', 'East Side Gallery', 'Culture', 'free', 'Friedrichshain', 'Mühlenstraße 3-100, 10243 Berlin', '1,3 km du Mur de Berlin recouverts de fresques.', 'Commencez côté Ostbahnhof, finissez sur l''Oberbaumbrücke.', false, 'img/s17.jpg', 'Joachim F. Thurn · CC BY-SA 3.0 de · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Bundesarchiv_B_145_Bild-F088809-0038,_Berlin,_East_Side_Gallery.jpg'),
  ('s18', 'berlin', 'Markthalle Neun', 'Restaurant', 'p2', 'Kreuzberg', 'Eisenbahnstraße 42/43, 10997 Berlin', 'Halle de marché de 1891, street food le jeudi soir.', 'Le Street Food Thursday commence à 17h.', true, '', '', ''),
  ('s19', 'berlin', 'Mustafa''s Gemüse Kebap', 'Restaurant', 'p1', 'Kreuzberg', 'Mehringdamm 32, 10961 Berlin', 'Le kebab de légumes grillés le plus connu de Berlin.', 'Comptez 30 à 60 minutes de queue le week-end.', false, '', '', ''),
  ('s20', 'berlin', 'Berghain', 'Bar & nuit', 'p2', 'Friedrichshain', 'Am Wriezener Bahnhof, 10243 Berlin', 'Club techno mythique installé dans une ancienne centrale électrique.', 'Pas de photos, et la sélection à l''entrée est stricte.', false, 'img/s20.jpg', 'Lear 21 · CC BY 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:1_Berlin_Berghain_NYE_01.jpg'),
  ('s21', 'amsterdam', 'Vondelpark', 'Activité', 'free', 'Oud-Zuid', 'Vondelpark, 1071 AA Amsterdam', 'Le grand parc de la ville, à faire à vélo ou à pied.', 'Le théâtre en plein air est gratuit l''été.', false, 'img/s21.jpg', 'Dguendel · CC BY 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Amsterdam,_Vondelpark,_at_the_pond-2.jpg'),
  ('s22', 'amsterdam', 'Rijksmuseum', 'Culture', 'p2', 'Museumplein', 'Museumstraat 1, 1071 XX Amsterdam', 'Rembrandt, Vermeer et l''âge d''or néerlandais.', 'Réservez un créneau horaire en ligne.', true, 'img/s22.jpg', 'User:Voytikof · CC BY-SA 2.5 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Amsterdam_-_Rijksmuseum.jpg'),
  ('s23', 'amsterdam', 'Brouwerij ''t IJ', 'Bar & nuit', 'p1', 'Oost', 'Funenkade 7, 1018 AL Amsterdam', 'Brasserie artisanale au pied d''un moulin à vent.', 'La terrasse se remplit dès 16h quand il fait beau.', false, 'img/s23.jpg', 'SJSV · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Brouwerijhetij.jpg'),
  ('s24', 'amsterdam', 'Foodhallen', 'Restaurant', 'p2', 'Oud-West', 'Bellamyplein 51, 1053 AT Amsterdam', 'Ancien dépôt de tramways reconverti en halle de street food.', 'Idéal pour un groupe qui n''a pas les mêmes envies.', false, 'img/s24.jpg', 'SophieWikiAms · CC0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:De_Hallen_Amsterdam_2024_Entree_Tollensstraat.jpg'),
  ('s25', 'paris', 'Musée du Louvre', 'Culture', 'p2', '1er arrondissement', 'Rue de Rivoli, 75001 Paris', 'Le plus grand musée du monde, de la Joconde aux antiquités égyptiennes.', 'Réservez un créneau en ligne et entrez par le Carrousel du Louvre.', false, 'img/s25.jpg', 'Benh LIEU SONG (Flickr) · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Louvre_Museum_Wikimedia_Commons.jpg'),
  ('s26', 'paris', 'Basilique du Sacré-Cœur', 'Activité', 'free', 'Montmartre', '35 Rue du Chevalier de la Barre, 75018 Paris', 'La basilique blanche au sommet de Montmartre et sa vue sur tout Paris.', 'Redescendez par la rue de l''Abreuvoir, l''une des plus jolies de Paris.', false, 'img/s26.jpg', 'Arthur Weidmann · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Sacré_Coeur_Façade_1.jpg'),
  ('s27', 'paris', 'Jardin du Luxembourg', 'Activité', 'free', '6e arrondissement', 'Rue de Médicis, 75006 Paris', 'Le jardin préféré des Parisiens : chaises vertes, bassin et Palais du Sénat.', 'Prenez une chaise au bord du grand bassin, c''est gratuit.', false, 'img/s27.jpg', 'Kirua · Public domain · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:LuxembourgMontparnasse.JPG'),
  ('s28', 'paris', 'L''As du Fallafel', 'Restaurant', 'p1', 'Le Marais', '34 Rue des Rosiers, 75004 Paris', 'Le falafel le plus célèbre du Marais, à emporter ou sur place.', 'Fermé le samedi. La file avance vite.', false, '', '', ''),
  ('s29', 'paris', 'Marché des Enfants Rouges', 'Restaurant', 'p1', 'Le Marais', '39 Rue de Bretagne, 75003 Paris', 'Le plus vieux marché couvert de Paris, avec ses comptoirs de cuisines du monde.', 'Fermé le lundi. Arrivez avant 12h30 pour avoir une place.', false, 'img/s29.jpg', 'besopha · CC BY 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Marché_des_Enfants-Rouges,_Paris_May_2016.jpg'),
  ('s30', 'paris', 'Sainte-Chapelle', 'Culture', 'p2', 'Île de la Cité', '10 Boulevard du Palais, 75001 Paris', 'Une chapelle gothique entièrement entourée de vitraux du XIIIe siècle.', 'Venez par une journée ensoleillée pour voir les vitraux s''allumer.', false, 'img/s30.jpg', 'Tiraden · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Sainte-Chapelle_de_Paris_vue_du_Palais_de_justice.JPG'),
  ('s31', 'paris', 'Harry''s New York Bar', 'Bar & nuit', 'p2', 'Opéra', '5 Rue Daunou, 75002 Paris', 'Bar mythique de 1911, berceau revendiqué du Bloody Mary.', 'Le piano-bar du sous-sol s''anime en fin de soirée.', false, 'img/s31.jpg', 'Mitch Barrie from Costa Mesa, CA, USA · CC BY-SA 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Harrys_New_York_Bar_6,_Paris_2012.jpg'),
  ('s32', 'paris', 'Tour Eiffel', 'Activité', 'p2', '7e arrondissement', 'Champ de Mars, 5 Avenue Anatole France, 75007 Paris', 'Le symbole de Paris, à monter par les escaliers ou en ascenseur.', 'Les escaliers jusqu''au 2e étage coûtent moins cher que l''ascenseur.', false, 'img/s32.jpg', 'Benh LIEU SONG · Public domain · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Tour_Eiffel_Wikimedia_Commons.jpg'),
  ('s33', 'paris', 'Shakespeare and Company', 'Culture', 'free', 'Quartier latin', '37 Rue de la Bûcherie, 75005 Paris', 'Librairie anglophone face à Notre-Dame, refuge des écrivains depuis 1951.', 'Le café voisin a vue sur la cathédrale.', false, 'img/s33.jpg', 'Shadowgate from Novara, ITALY · CC BY 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Shakespeare_and_Company_bookstore,_Paris_13_August_2013.jpg'),
  ('s34', 'paris', 'Le Procope', 'Restaurant', 'p3', 'Saint-Germain-des-Prés', '13 Rue de l''Ancienne Comédie, 75006 Paris', 'Le plus ancien café de Paris (1686), devenu restaurant de cuisine française.', 'Demandez une table à l''étage, dans les salons d''époque.', false, 'img/s34.jpg', 'Jean-Marie Hullot from France · CC BY-SA 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Le_Procope_1,_Paris_2010.jpg'),
  ('s35', 'paris', 'Parc des Buttes-Chaumont', 'Activité', 'free', '19e arrondissement', '1 Rue Botzaris, 75019 Paris', 'Parc vallonné avec falaises, cascade et temple perché au-dessus du lac.', 'Montez au temple de la Sibylle pour la vue sur le Sacré-Cœur.', false, 'img/s35.jpg', 'O.Taris · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:ParcDesButtesChaumont.JPG'),
  ('s36', 'lisbonne', 'Tour de Belém', 'Culture', 'p1', 'Belém', 'Av. Brasília, 1400-038 Lisboa', 'Tour manuéline du XVIe siècle posée sur le Tage, classée à l''UNESCO.', 'Le billet combiné avec le monastère des Hiéronymites revient moins cher.', false, 'img/s36.jpg', 'Lisbon Photoshoots · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Belém_Tower_in_Lisbon,_Portugal.jpg'),
  ('s37', 'lisbonne', 'Monastère des Hiéronymites', 'Culture', 'p2', 'Belém', 'Praça do Império, 1400-206 Lisboa', 'Chef-d''œuvre manuélin et son cloître sculpté, à deux pas des pastéis.', 'L''église est gratuite, seul le cloître est payant.', false, 'img/s37.jpg', 'Holger Uwe Schmitt · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:1502_legte_König_Manuel_I._den_Grundstein_für_das_Hieronymus_Kloster_in_Lissabon._06.jpg'),
  ('s38', 'lisbonne', 'Castelo de São Jorge', 'Culture', 'p2', 'Alfama', 'Rua de Santa Cruz do Castelo, 1100-129 Lisboa', 'Château maure qui domine l''Alfama, avec ses remparts et ses paons.', 'Restez jusqu''au coucher du soleil depuis les remparts.', false, 'img/s38.jpg', 'CC BY-SA 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Castelo_Sao_Jorge_Lisboa_1.JPG'),
  ('s39', 'lisbonne', 'Elevador de Santa Justa', 'Activité', 'p1', 'Baixa', 'Rua do Ouro, 1150-060 Lisboa', 'Ascenseur néogothique en fer forgé qui relie la Baixa au Chiado.', 'Le passe Viva Viagem 24h inclut le trajet.', false, 'img/s39.jpg', 'Luca Galuzzi (Lucag) · CC BY-SA 2.5 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Lisbon_(Lisboa)_historic_elevator_Santa_Justa_Luca_Galuzzi_2006.jpg'),
  ('s40', 'lisbonne', 'Oceanário de Lisboa', 'Activité', 'p2', 'Parque das Nações', 'Esplanada Dom Carlos I, 1990-005 Lisboa', 'L''un des plus grands aquariums d''Europe, autour d''un bassin central géant.', 'Comptez deux heures, et réservez en ligne le week-end.', false, 'img/s40.jpg', 'Shadowgate from Novara, ITALY · CC BY 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Lisbon_Oceanarium_(34535938846).jpg'),
  ('s41', 'lisbonne', 'A Ginjinha', 'Bar & nuit', 'p1', 'Rossio', 'Largo de São Domingos 8, 1100-201 Lisboa', 'Minuscule comptoir de 1840 qui sert la liqueur de griotte locale.', 'Demandez-la « com elas », avec les cerises.', false, '', '', ''),
  ('s42', 'lisbonne', 'Cervejaria Ramiro', 'Restaurant', 'p3', 'Intendente', 'Av. Almirante Reis 1, 1150-007 Lisboa', 'Temple des fruits de mer : crevettes à l''ail, crabe et prego en dessert.', 'Pas de réservation, venez à l''ouverture.', false, '', '', ''),
  ('s43', 'lisbonne', 'Soirée au Bairro Alto', 'Bar & nuit', 'p1', 'Bairro Alto', 'Rua do Diário de Notícias, 1200-141 Lisboa', 'Ruelles pleines de petits bars où l''on boit dans la rue jusque tard.', 'L''ambiance démarre vers 23h, les bières coûtent quelques euros.', false, 'img/s43.jpg', 'CC BY-SA 2.5 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Bairro_Alto_Lisboa_1.JPG'),
  ('s44', 'lisbonne', 'Praça do Comércio', 'Activité', 'free', 'Baixa', 'Praça do Comércio, 1100-148 Lisboa', 'Immense place ouverte sur le Tage, encadrée d''arcades jaunes.', 'Passez sous l''Arco da Rua Augusta pour rejoindre la Baixa.', false, 'img/s44.jpg', 'Deensel · CC BY 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Aerial_view_of_Praça_do_Comércio_and_Baixa_Pombalina_(cropped_and_retouched).jpg'),
  ('s45', 'lisbonne', 'Musée Calouste Gulbenkian', 'Culture', 'p1', 'Avenidas Novas', 'Av. de Berna 45A, 1067-001 Lisboa', 'Collection d''art de l''Antiquité à Lalique, dans un jardin moderniste.', 'Le jardin est en accès libre, parfait pour une pause.', false, 'img/s45.jpg', 'Kent Wang · CC BY 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Calouste_Gulbenkian_Museum_Exterior_37.jpg'),
  ('s46', 'lisbonne', 'MAAT', 'Culture', 'p1', 'Belém', 'Av. Brasília, 1300-598 Lisboa', 'Musée d''art, d''architecture et de technologie au toit ondulé sur le Tage.', 'Le toit est accessible à pied, gratuitement.', false, 'img/s46.jpg', 'Kent Wang · CC BY 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Exterior_of_Museu_de_Arte,_Arquitetura_e_Tecnologia_67.jpg'),
  ('s47', 'barcelone', 'Park Güell', 'Activité', 'p2', 'Gràcia', 'Carrer d''Olot, 08024 Barcelona', 'Le parc de Gaudí, ses mosaïques et son banc ondulé face à la mer.', 'Réservez le premier créneau du matin pour éviter la foule.', false, 'img/s47.jpg', 'Canaan · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Güell_BCN_edited.jpg'),
  ('s48', 'barcelone', 'Casa Batlló', 'Culture', 'p2', 'Eixample', 'Passeig de Gràcia 43, 08007 Barcelona', 'La maison aux balcons en forme de masques, chef-d''œuvre de Gaudí.', 'La façade s''admire gratuitement de nuit, quand elle est éclairée.', false, 'img/s48.jpg', 'Enfo · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:05_Casa_Batlló.jpg'),
  ('s49', 'barcelone', 'Museu Picasso', 'Culture', 'p2', 'El Born', 'Carrer de Montcada 15-23, 08003 Barcelona', 'Les années de formation de Picasso dans cinq palais médiévaux.', 'Gratuit le jeudi en fin d''après-midi, sur réservation.', false, 'img/s49.jpg', 'Pere López · CC BY-SA 3.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Palau_Berenguer_d''Aguilar.jpg'),
  ('s50', 'barcelone', 'Plage de la Barceloneta', 'Activité', 'free', 'La Barceloneta', 'Platja de la Barceloneta, 08003 Barcelona', 'La plage urbaine la plus animée, à dix minutes à pied de la vieille ville.', 'Remontez vers la Nova Icària pour plus de place.', false, 'img/s50.jpg', 'Kuba Bożanowski from Warsaw, Poland · CC BY 2.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Barcelona_(16877599244).jpg'),
  ('s51', 'barcelone', 'Colline de Montjuïc', 'Activité', 'free', 'Sants-Montjuïc', 'Parc de Montjuïc, 08038 Barcelona', 'Jardins, musées et château sur la colline qui surplombe le port.', 'Montez par les escalators depuis la Plaça d''Espanya.', false, 'img/s51.jpg', 'Didier Descouens · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:(Barcelona)_Palau_Nacional_de_Montjuïc_-_La_cúpula_central_vista_des_de_la_terrassa_oest.jpg'),
  ('s52', 'barcelone', 'Cal Pep', 'Restaurant', 'p3', 'El Born', 'Plaça de les Olles 8, 08003 Barcelona', 'Comptoir à tapas de poissons et fruits de mer, servis au gré du chef.', 'Placez-vous au comptoir et laissez Pep choisir.', false, '', '', ''),
  ('s53', 'barcelone', 'Paradiso', 'Bar & nuit', 'p2', 'El Born', 'Carrer de Rera Palau 4, 08003 Barcelona', 'Bar à cocktails caché derrière la porte d''un frigo de pastrami bar.', 'Venez tôt en soirée, la file s''allonge vite.', false, '', '', ''),
  ('s54', 'barcelone', 'Palau de la Música Catalana', 'Culture', 'p2', 'Sant Pere', 'Carrer del Palau de la Música 4-6, 08003 Barcelona', 'Salle de concert moderniste à la verrière colorée, classée à l''UNESCO.', 'Un billet de concert coûte parfois moins cher que la visite guidée.', false, 'img/s54.jpg', 'Ralf Roletschek · GFDL 1.2 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:22_11_01_Palau_DSCF2611_52502512616_cc1e7db845_k.jpg'),
  ('s55', 'barcelone', 'Quimet & Quimet', 'Bar & nuit', 'p2', 'Poble-sec', 'Carrer del Poeta Cabanyes 25, 08004 Barcelona', 'Minuscule bodega aux murs couverts de bouteilles, montaditos et conserves fines.', 'On mange debout, et c''est fermé le week-end.', false, '', '', ''),
  ('s56', 'barcelone', 'Balade dans le Barri Gòtic', 'Activité', 'free', 'Barri Gòtic', 'Plaça Nova, 08002 Barcelona', 'Ruelles médiévales, cathédrale et places cachées au cœur de la vieille ville.', 'Cherchez la Plaça Sant Felip Neri, la plus calme du quartier.', false, 'img/s56.jpg', 'C messier · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Palau_Reial_Major_2574.jpg'),
  ('s57', 'barcelone', 'Mercat de Santa Caterina', 'Restaurant', 'p1', 'Sant Pere', 'Av. de Francesc Cambó 16, 08003 Barcelona', 'Marché au toit ondulé multicolore, plus calme que la Boqueria.', 'Le bar Joan, à l''intérieur, sert un menu du midi bon marché.', false, 'img/s57.jpg', 'Albert Prat · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Façana_Santa_Caterina.jpg'),
  ('s58', 'rome', 'Colisée', 'Culture', 'p2', 'Monti', 'Piazza del Colosseo, 00184 Roma', 'Le plus grand amphithéâtre romain, avec le Forum et le Palatin.', 'Le billet inclut le Forum romain et le Palatin, gardez une journée.', false, 'img/s58.jpg', 'FeaturedPics · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Colosseo_2020.jpg'),
  ('s59', 'rome', 'Fontaine de Trevi', 'Activité', 'free', 'Trevi', 'Piazza di Trevi, 00187 Roma', 'La fontaine baroque où l''on jette une pièce pour revenir à Rome.', 'Venez avant 8h pour la voir sans la foule.', false, 'img/s59.jpg', 'NikonZ7II · CC BY-SA 4.0 · Wikimedia Commons', 'https://commons.wikimedia.org/wiki/File:Trevi_Fountain_-_Roma.jpg'),
